  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ21",
      "role": "primary",
      "technique": "Oscillatory shear rheometry",
      "why": "Measures the viscoelastic properties and shear storage modulus (stiffness) of soft hydrogels under controlled strain or stress conditions.",
      "accessories_to_confirm": [
        "Parallel plate or cone-and-plate geometry suitable for hydrogels",
        "Temperature-controlled Peltier stage or solvent trap to prevent sample drying"
      ]
    },
    {
      "instrument_id": "EQ19",
      "role": "primary",
      "technique": "Oscillatory shear rheometry",
      "why": "Alternative hybrid rheometer capable of measuring the storage and loss moduli to determine hydrogel stiffness.",
      "accessories_to_confirm": [
        "Hydrogel-compatible testing geometry (e.g., parallel plates)",
        "Solvent trap and temperature control fixture"
      ]
    }
  ],
  "not_available": [
    {
      "technique": "Atomic Force Microscopy (AFM) / Nanoindentation",
      "why_useful": "Enables micro- or nanoscale mapping of local Young's modulus on soft, hydrated samples directly via a microscope-based technique."
