      "accessories_to_confirm": [
        "Standard or Tzero aluminum sample pans and lids",
        "Sample crimper/encapsulating press",
        "Nitrogen purge gas supply"
      ]
    },
    {
      "instrument_id": "EQ21",
      "role": "supplementary",
      "technique": "Temperature-ramp melt rheometry",
