        "Gaseous secondary electron detector (GSED) or backscattered electron detector for low-vacuum mode"
      ]
    },
    {
      "instrument_id": "EQ02",
      "role": "supplementary",
      "technique": "Digital Light Processing (DLP) 3D printing",
      "why": "It enables high-resolution photopolymerization of resin into designed porous scaffold structures for subsequent analysis.",
      "accessories_to_confirm": [
        "Compatible photopolymer resin",
