{
  "measurement_needs": [
    "Quantitative 3D surface topography mapping at the nanoscale",
    "RMS surface roughness (Sq/Rq) determination over a 5 × 5 µm field of view"
  ],
  "objective_met": false,
  "recommendations": [
    {
